package fi.jakke77.saawidget;

import android.app.Activity;
import android.app.AlertDialog;
import android.appwidget.AppWidgetManager;
import android.content.Intent;
import android.graphics.Color;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public final class MainActivity extends Activity {
    private int widgetId=-1, generation; private boolean configuring; private WidgetConfig config;
    private TextView location,temperature,summary,status,attribution; private ForecastGraphView graph; private Button refresh;
    private static final int BG=Color.rgb(23,18,31),SURFACE=Color.rgb(43,27,51),TEXT=Color.rgb(255,244,237),MUTED=Color.rgb(198,174,189),ORANGE=Color.rgb(233,84,32);
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle bundle){super.onCreate(bundle);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);configuring=AppWidgetManager.ACTION_APPWIDGET_CONFIGURE.equals(getIntent().getAction());if(configuring){setResult(RESULT_CANCELED);if(widgetId<0){finish();return;}}config=WidgetConfig.load(this,widgetId);build();WeatherUpdateJobService.schedule(this);load();if(configuring)settings();}
    private TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));return v;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextColor(TEXT);b.setOnClickListener(v->action.run());return b;}
    private void build(){
        LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setBackgroundColor(BG);outer.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(16),dp(20),dp(24));scroll.addView(body);outer.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
        TextView title=text("Ajanlaskut · Sää",28,TEXT);body.addView(title);body.addView(text(widgetId==-1?"Sää taskuun ja kotinäytölle":"Kotinäytön widgetin sää ja asetukset",14,MUTED));
        LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setBackgroundColor(SURFACE);card.setPadding(dp(18),dp(14),dp(18),dp(14));LinearLayout.LayoutParams cardParams=new LinearLayout.LayoutParams(-1,-2);cardParams.topMargin=dp(18);body.addView(card,cardParams);
        location=text(config.place,20,TEXT);card.addView(location);temperature=text("—",56,TEXT);card.addView(temperature);summary=text("Ennuste nyt · "+WidgetConfig.providerName(config.provider),15,MUTED);card.addView(summary);status=text("Ladataan ennustetta…",13,MUTED);card.addView(status);
        LinearLayout buttons=new LinearLayout(this);refresh=button("Päivitä",()->{load();WeatherUpdateJobService.refreshNow(this);});buttons.addView(refresh,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(button("Paikka ja asetukset",this::settings),new LinearLayout.LayoutParams(0,-2,1));body.addView(buttons);
        body.addView(text("Seuraavat tunnit",22,TEXT));graph=new ForecastGraphView(this);body.addView(graph,new LinearLayout.LayoutParams(-1,dp(260)));body.addView(text("Oranssi: lämpötila °C · Sininen: sade mm/h · —: sade puuttuu",12,MUTED));attribution=text(SourceUrls.attribution(config.provider),12,MUTED);body.addView(attribution);
        body.addView(text("Palvelujen omat sääkartat",22,TEXT));body.addView(text("Kartat ja Windyn ennuste avautuvat palvelun omalle sivulle. Sen eväste- ja sijaintivalinnat säilyvät.",13,MUTED));
        body.addView(button("Foreca · sadetutka",()->web("Foreca · sadetutka",SourceUrls.FORECA_RAIN)));body.addView(button("Ilmatieteen laitos · sadekartta",()->web("Ilmatieteen laitos · sadekartta",SourceUrls.FMI_RAIN)));
        body.addView(button("Windy · tuntiennuste",()->web("Windy · tuntiennuste",SourceUrls.windyForecast(config))));body.addView(button("Windy · sääkartta",()->web("Windy · sääkartta",SourceUrls.windyMap(config))));body.addView(button("RainViewer · sadetutka",()->web("RainViewer · sadetutka",SourceUrls.RAINVIEWER)));
        body.addView(text("Sää kotinäytölle",22,TEXT));body.addView(text("Paina kotinäytön tyhjää kohtaa pitkään → Widgetit → Ajanlaskut · Sää. Valitse pieni 1 × 1 lämpötilawidget, 2 × 1 sääkortti tai suurempi ennustewidget. Jokaisella on oma sääpalvelu ja paikka.",14,MUTED));
        body.addView(text("Pieni widget näyttää nykyisen tunnin ennusteen, ei havaintoasemalta mitattua lämpötilaa. Android ja virransäästö voivat viivästyttää automaattista päivitystä. Tunnit käyttävät valitun paikan aikavyöhykettä.",13,MUTED));
        body.addView(button("Tietoa sovelluksesta",this::about));setContentView(outer);
    }
    private void web(String title,String url){startActivity(new Intent(this,WeatherWebActivity.class).putExtra("title",title).putExtra("url",url));}
    private void load(){int turn=++generation;WidgetConfig selected=config;ForecastData cached=WeatherRepository.get(this).getCached(selected);display(cached,cached==null?"Ladataan ennustetta…":"Päivitetään välimuistista…");refresh.setEnabled(false);WeatherRepository.get(this).load(selected,(data,error)->{if(isFinishing()||turn!=generation)return;refresh.setEnabled(true);display(data,error);for(int id:WeatherWidgetUpdater.widgetIds(this))WeatherWidgetUpdater.renderCached(this,id);});}
    private void display(ForecastData data,String error){location.setText(config.place);attribution.setText(SourceUrls.attribution(config.provider));graph.setForecast(data,config);ForecastData.Hour now=data==null?null:data.current(System.currentTimeMillis());temperature.setText(now==null?"—":String.format(Locale.getDefault(),"%.0f°",now.tempC));summary.setText("Ennuste nyt · "+WidgetConfig.providerName(config.provider)+(now==null?"":" · tuuli "+String.format(Locale.getDefault(),"%.1f",now.windMps)+" m/s"));
        if(data==null){status.setText(error==null||error.isEmpty()?"Ennustetta ei ole vielä saatavilla":error);}else{String stamp=DateTimeFormatter.ofPattern("HH:mm",Locale.getDefault()).withZone(ZoneId.of(config.timezone)).format(Instant.ofEpochMilli(data.fetchedAt));String label=data.stale(System.currentTimeMillis())?"Vanha välimuisti / verkkoyhteys katkennut":"Päivitetty";status.setText(label+" "+stamp+(error==null||error.isEmpty()?"":" · "+error)+(now==null?" · Nykyiselle tunnille ei ole arvoa":""));}temperature.setContentDescription(now==null?"Nykyisen tunnin lämpötilaennuste puuttuu":"Nykyisen tunnin ennuste "+Math.round(now.tempC)+" astetta, "+WidgetConfig.providerName(config.provider));}
    private EditText field(LinearLayout body,String label,String value,int type){body.addView(text(label,13,MUTED));EditText edit=new EditText(this);edit.setText(value);edit.setTextColor(TEXT);edit.setInputType(type);edit.setSingleLine(true);body.addView(edit);return edit;}
    private Spinner choice(LinearLayout body,String label,String[] values,int selected){body.addView(text(label,13,MUTED));Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,values);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);s.setSelection(selected);body.addView(s);return s;}
    private void settings(){ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(8),dp(18),dp(16));scroll.addView(body);
        String[] providers={"yr","fmi","openmeteo"},palettes={"ubuntu","copper","mint","night"};int pi=0,ci=0;for(int i=0;i<providers.length;i++)if(providers[i].equals(config.provider))pi=i;for(int i=0;i<palettes.length;i++)if(palettes[i].equals(config.palette))ci=i;
        Spinner provider=choice(body,"Lämpötilan ja ennusteen sääpalvelu",new String[]{"Yr · MET Norway","Ilmatieteen laitos","Open-Meteo"},pi);body.addView(text("Foreca ja Windy ovat omissa verkkonäkymissään. Niiden kotinäyttödata vaatii erillisen maksullisen API-palvelun.",12,MUTED));
        EditText search=field(body,"Hae paikkakuntaa","",InputType.TYPE_CLASS_TEXT);Button find=button("Hae paikka",()->{});body.addView(find);
        EditText place=field(body,"Näytettävä paikan nimi",config.place,InputType.TYPE_CLASS_TEXT);int decimals=InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED;
        EditText lat=field(body,"Leveysaste −90…90",Double.toString(config.latitude),decimals),lon=field(body,"Pituusaste −180…180",Double.toString(config.longitude),decimals);EditText timezone=field(body,"Aikavyöhyke",config.timezone,InputType.TYPE_CLASS_TEXT);
        Spinner palette=choice(body,"Widgetin värit",new String[]{"Ubuntu · oranssi","Kupari","Minttu","Yö · sininen"},ci),hours=choice(body,"Ennusteen pituus",new String[]{"12 tuntia","24 tuntia"},config.hours==24?1:0);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(configuring?"Lisää sääwidget":"Sää ja widgetin asetukset").setView(scroll).setNegativeButton("Peruuta",(d,w)->{if(configuring)finish();}).setPositiveButton(configuring?"Lisää widget":"Tallenna",null).create();
        find.setOnClickListener(v->{String query=search.getText().toString().trim();if(query.length()<2){search.setError("Kirjoita vähintään kaksi merkkiä");return;}find.setEnabled(false);WeatherRepository.get(this).searchPlaces(query,(places,error)->{if(isFinishing()||!dialog.isShowing())return;find.setEnabled(true);if(!error.isEmpty()){search.setError(error);return;}String[] names=new String[places.size()];for(int i=0;i<names.length;i++)names[i]=places.get(i).name;new AlertDialog.Builder(this).setTitle("Valitse paikka").setItems(names,(d,index)->{WeatherRepository.Place chosen=places.get(index);place.setText(chosen.name);lat.setText(Double.toString(chosen.latitude));lon.setText(Double.toString(chosen.longitude));timezone.setText(chosen.timezone);}).setNegativeButton("Peruuta",null).show();});});
        dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{config=new WidgetConfig(providers[provider.getSelectedItemPosition()],place.getText().toString(),Double.parseDouble(lat.getText().toString().replace(',','.')),Double.parseDouble(lon.getText().toString().replace(',','.')),timezone.getText().toString().trim(),palettes[palette.getSelectedItemPosition()],hours.getSelectedItemPosition()==1?24:12);config.save(this,widgetId);WeatherUpdateJobService.schedule(this);WeatherUpdateJobService.refreshNow(this);if(widgetId!=-1)WeatherWidgetUpdater.refresh(this,widgetId);else WeatherWidgetUpdater.updateAll(this);dialog.dismiss();if(configuring){setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();}else load();}catch(Exception e){place.setError(e.getMessage()==null?"Tarkista paikan nimi, koordinaatit ja aikavyöhyke":e.getMessage());}}));dialog.show();
    }
    private void about(){new AlertDialog.Builder(this).setTitle("Ajanlaskut · Sää "+BuildConfig.VERSION_NAME).setMessage("Itsenäinen Android-sovellus ja kotinäytön sääwidgetit.\n\nYr/MET Norway, Ilmatieteen laitos ja Open-Meteo: avoimet sääennusteet, CC BY 4.0. Säät ovat kyseisen palvelun tuntiennusteita.\n\nForecan, Ilmatieteen laitoksen, Windyn ja RainViewerin omat verkkosivut kuuluvat palveluilleen. Sivujen sisältöä ei kopioida kotinäyttöwidgetteihin.\n\nAsetukset ja välimuisti säilytetään tämän sovelluksen sisällä. Paikkahaku välittää hakutermin Open-Meteolle; säähaut välittävät valitut koordinaatit sääpalvelulle. Sovellus ei pyydä puhelimen paikannusta.\n\nAutomaattinen päivitys noin 30 minuutin välein, Androidin virransäästön sallimana. Päivitä käyttää tarvittaessa API-palvelun vähintään 15 minuutin välimuistia.").setPositiveButton("Sulje",null).show();}
    @Override protected void onDestroy(){generation++;super.onDestroy();}
}
